--- /dev/null
+++ b/src/components/BookCard/BookCard.tsx
@@ -0,0 +1,20 @@
+import type { Book } from '../../types';
+import './BookCard.css';
+
+interface BookCardProps {
+  book: Book;
+  onClick: (id: string) => void;
+}
+
+export default function BookCard({ book, onClick }: BookCardProps): JSX.Element {
+  return (
+    <article
+      className="book-card"
+      role="button"
+      tabIndex={0}
+      aria-label={`${book.title} by ${book.author}`}
+      onClick={() => onClick(book.id)}
+    >
+      <h3>{book.title}</h3>
+      <p>{book.author}</p>
+    </article>
+  );
+}

